/*
 * A042642  Numerators of continued fraction convergents to sqrt(851).
 * https://oeis.org/A042642
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   a(n) = numerator of the n-th convergent of sqrt(851) Recurrence
 *            for the convergents p: p[-2] = 0, p[-1] = 1 p[n] = a_n * p[n-1]
 *            + p[n-2] where the continued‑fraction coefficients a_n are
 *            generated by a_0 = floor(sqrt(851)) = 29 m_0 = 0, d_0 = 1 for k
 *            ≥ 1: m_k = d_{k-1} * a_{k-1} - m_{k-1} d_k = (...
 * Range:     u8 n <= 2, u16 n <= 6, u32 n <= 14, u64 n <= 30, u128 n <= 62,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* constants for sqrt(851) */
    const idx_t D   = 851ULL;   /* D = 851 */
    const idx_t a0  = 29ULL;    /* floor(sqrt(D)) */

    /* continued‑fraction state variables */
    idx_t m   = 0;          /* m_0 */
    idx_t d   = 1;          /* d_0 */
    idx_t a_prev = a0;      /* a_{k-1} */

    /* convergents p_{-2} and p_{-1} */
    seq_t p_prev2 = 0;      /* p[-2] */
    seq_t p_prev1 = 1;      /* p[-1] */
    seq_t p = 0;            /* p_k */
    idx_t a_k;              /* current continued‑fraction coefficient */

    /* iterate up to index n */
    for (idx_t k = 0; k <= n; ++k)
    {
        if (k == 0)
        {
            a_k = a_prev;     /* a_0 */
        }
        else
        {
            /* next state of the continued fraction */
            idx_t m_next = d * a_prev - m;
            idx_t d_next = (D - m_next * m_next) / d;
            idx_t a_next = (a0 + m_next) / d_next;

            m   = m_next;
            d   = d_next;
            a_prev = a_next;
            a_k   = a_next;
        }

        /* compute next convergent numerator */
        p = (seq_t)a_k * p_prev1 + p_prev2;
        p_prev2 = p_prev1;
        p_prev1 = p;
    }

    return p_prev1;
}
